WITH base AS (SELECT *, ROUND(duration_sec * 1.1, 2) AS duration_sec_adjusted, COALESCE(page, 'DIRECT') AS page_clean FROM web_events WHERE page IS DISTINCT FROM '/cart'), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM base), sessions_web_events AS (SELECT id, session_id, event_type, page, event_time, duration_sec, duration_sec_adjusted, page_clean, SUM(is_new_burst) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM flagged), enriched AS (SELECT e.id, e.session_id, e.event_type, e.duration_sec, e.page_clean, s.browser, s.device, s.country FROM sessions_web_events e LEFT JOIN sessions s ON e.session_id = s.id WHERE s.country = 'DE'), enriched_web_events AS (SELECT id, session_id, event_type, duration_sec, browser, device, CUME_DIST() OVER (PARTITION BY browser, session_id ORDER BY duration_sec DESC NULLS FIRST) AS duration_sec_cume_dist, LAST_VALUE(device) IGNORE NULLS OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_device FROM enriched), latest AS (SELECT id, session_id, duration_sec, browser, device, duration_sec_cume_dist, last_known_device FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device, browser ORDER BY duration_sec NULLS FIRST, id) AS dedup_rank FROM enriched_web_events) t WHERE dedup_rank = 1), with_dims AS (SELECT e.id, e.session_id, e.duration_sec, e.browser, e.last_known_device, b.browser AS session_browser, b.country FROM latest e JOIN sessions b ON e.session_id = b.id) SELECT CASE WHEN duration_sec >= 371 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, browser, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles FROM with_dims GROUP BY CASE WHEN duration_sec >= 371 THEN 'PREMIUM' ELSE 'STANDARD' END, browser HAVING duration_sec_stddev < 1000000
